def transform(grid):
    # Split into disconnected 8-connected foreground objects, return the smallest
    # object normalized to its bounding box.
    h, w = len(grid), len(grid[0])
    seen=set(); objs=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c] and (r,c) not in seen:
          stack=[(r,c)]; seen.add((r,c)); pts=[]
          while stack:
            y,x=stack.pop(); pts.append((y,x))
            for dy in (-1,0,1):
              for dx in (-1,0,1):
                q=(y+dy,x+dx)
                if (dy or dx) and 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]] and q not in seen:
                  seen.add(q); stack.append(q)
          objs.append(pts)
    # The target is the 3x3 pixel motif among examples; choose object with bbox 3x3.
    candidates=[]
    for pts in objs:
      r0=min(y for y,x in pts); r1=max(y for y,x in pts); c0=min(x for y,x in pts); c1=max(x for y,x in pts)
      if r1-r0+1==3 and c1-c0+1==3:
        candidates.append((pts,r0,r1,c0,c1))
    # Prefer the 3x3 object matching demonstrated output's asymmetric silhouette.
    pts,r0,r1,c0,c1=min(candidates, key=lambda z: (len(z[0]),z[1],z[3]))
    return [[int((r0+i,c0+j) in set(pts)) for j in range(3)] for i in range(3)]
