def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c] and (r,c) not in seen:
          st=[(r,c)]; seen.add((r,c)); pts=[]
          while st:
            y,x=st.pop(); pts.append((y,x))
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
              a,b=y+dy,x+dx
              if 0<=a<h and 0<=b<w and grid[a][b] and (a,b) not in seen:
                seen.add((a,b)); st.append((a,b))
          comps.append(pts)
    # Output is the sparse/irregular symbol in the set of motifs, excluding large
    # filled distractor blobs; use the compact motif component(s).
    cand=[]
    for pts in comps:
      r0=min(y for y,x in pts);r1=max(y for y,x in pts);c0=min(x for y,x in pts);c1=max(x for y,x in pts)
      bh,bw=r1-r0+1,c1-c0+1
      if 3<=bh<=5 and 3<=bw<=5:
        cand.append((pts,r0,r1,c0,c1))
    # the target is lowest (last) small motif in the arrangement
    pts,r0,r1,c0,c1=max(cand,key=lambda z:z[2])
    ps=set(pts)
    return [[int((r0+i,c0+j) in ps) for j in range(c1-c0+1)] for i in range(r1-r0+1)]
