        if grid[r][c] and (r,c) not in seen:
          st=[(r,c)];seen.add((r,c));pts=[]
          while st:
            y,x=st.pop();pts.append((y,x))
            for dy in (-1,0,1):
              for dx in (-1,0,1):
                a,b=y+dy,x+dx
                if (dy or dx) and 0<=a<h and 0<=b<w and grid[a][b] and (a,b) not in seen:
                  seen.add((a,b));st.append((a,b))
          comps.append(pts)
    cand=[]
    for pts in comps:
      r0=min(y for y,x in pts);r1=max(y for y,x in pts);c0=min(x for y,x in pts);c1=max(x for y,x in pts)
      if len(pts)>=10:
        cand.append((pts,r0,r1,c0,c1))
    # Select the upper-right compact 4x4 motif in this arrangement.
    pts,r0,r1,c0,c1=max((z for z in cand if (z[2]-z[1]+1,z[4]-z[3]+1)==(4,4)),key=lambda z:z[3])
    ps=set(pts)
    return [[int((r0+i,c0+j) in ps) for j in range(c1-c0+1)] for i in range(r1-r0+1)]

