def transform(grid):
    # Find 8-connected objects. In this task, extract the smallest upper-right
    # 4x4 symbol, the compact pattern among larger distractor symbols.
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c] and (r,c) not in seen:
          stack=[(r,c)];seen.add((r,c));pts=[]
          while stack:
            y,x=stack.pop();pts.append((y,x))
            for dy in (-1,0,1):
              for dx in (-1,0,1):
                a,b=y+dy,x+dx
                if (dy or dx) and 0<=a<h and 0<=b<w and grid[a][b] and (a,b) not in seen:
                  seen.add((a,b));stack.append((a,b))
          comps.append(pts)
    cand=[]
    for pts in comps:
      r0=min(y for y,x in pts);r1=max(y for y,x in pts);c0=min(x for y,x in pts);c1=max(x for y,x in pts)
      if (r1-r0+1,c1-c0+1)==(4,4): cand.append((pts,r0,r1,c0,c1))
    # choose compact symbol by minimum foreground count
    pts,r0,r1,c0,c1=min(cand,key=lambda z:len(z[0]))
    ps=set(pts)
    return [[int((r0+i,c0+j) in ps) for j in range(4)] for i in range(4)]
